import java.util.Scanner;

public class C {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();

        System.out.println(compute(a, b, l, r));
    }

    static int compute(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] patternArr = new int[3 * (a + b) + 1];
        int tempVal = 0;

        for (int i = 1; i <= a; i++) {
            patternArr[i] = i;
            tempVal = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            patternArr[i] = tempVal;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int count = 1;
            while (containsInRange(patternArr, count, a + b - a + 1, i - 1))
                count++;
            patternArr[i] = count;
            tempVal = patternArr[i];
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            patternArr[i] = tempVal;
        }

        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            patternArr[i] = patternArr[i - (a + b)];
        }

        int[] coverageArr = new int[25];
        int startIdx = l % (a + b);
        if (startIdx == 0) startIdx += a + b;
        int endIdx = r - l + startIdx;
        if (endIdx < startIdx) endIdx += a + b;

        for (int i = startIdx; i <= endIdx; i++) {
            coverageArr[patternArr[i]] = 1;
        }

        int total = 0;
        for (int i = 1; i <= 24; i++)
            total += coverageArr[i];

        return total;
    }

    static boolean containsInRange(int[] arr, int val, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == val)
                return true;
        }
        return false;
    }
}
